function listingCarGPTFilters(){
 const profile=state.context.searchProfile||state.profile;
 const band=homePriceBand(profile.budget);const range=band?[band.min,band.max]:String(profile.budget).startsWith('search:')?profile.budget.split(':').slice(1).map(Number):(BUDGETS.find(b=>b[0]===profile.budget)||BUDGETS.at(-1)).slice(2);
 return {city:profile.city,min:range[0],max:range[1],body:profile.body,make:profile.make,model:profile.model,fuel:profile.fuel,transmission:profile.transmission};
}
function openCarGPT(selectedId,context={},trigger=null){const source=trigger||document.activeElement;const returnFocus=source?.dataset?.cargptNudge?`[data-cargpt-nudge="${CSS.escape(source.dataset.cargptNudge)}"]`:source?.dataset?.fdAction?'[data-fd-action="assistant"]':source?.dataset?.action?`[data-action="${source.dataset.action}"]`:null;const enter=()=>{state.onboarding=false;if(!carGPTSession)carGPTSession=createCarGPTSession({city:state.profile.city||'Gurugram'});if(context.listingFilters)carGPTSession.setListingContext(context.listingFilters);if(selectedId)carGPTSession.selectCar(typeof selectedId==='object'?selectedId:ALL_DEMO_CARS.find(car=>car.id===selectedId)||selectedId,{entry:true});go('cargpt',{returnToBottomNav:['home','orders','garage'].includes(state.route),returnFocus,...context});};revealCarGPT({trigger,enter});}
function icon(name){return iconMarkup(name);}
function glass(i,size='',cls=''){return glassArtwork(i,cls);}
function action(label,act,value='',cls='primary',extra=''){return `<button class="${cls}" data-action="${act}" data-value="${e(value)}" ${extra}>${e(label)}</button>`;}
function choice(label,act,value='',sub='',g=null,selected=null,make=''){return `<button class="choice${selected?' selected':''}" data-action="${act}" data-value="${e(value)}" ${selected!==null?`aria-pressed="${!!selected}"`:''}>${make?makeLogoMarkup(make):g!==null?glass(g):''}<span class="choice-label">${e(label)}${sub?`<small>${e(sub)}</small>`:''}</span>${selected!==null?`<span class="check" aria-hidden="true">${icon("check")}</span>`:`<span class="chev" aria-hidden="true">${icon("next")}</span>`}</button>`;}
function field(label,name,placeholder='',value='',type='text',extra=''){return `<label class="field">${e(label)}<input name="${name}" type="${type}" placeholder="${e(placeholder)}" value="${e(value)}" ${extra}></label>`;}
function select(label,name,items,value=''){return `<label class="field">${label==='Make'?`<span class="make-field-label">${e(label)}${makeLogoMarkup(value)}</span>`:e(label)}<select name="${name}"><option value="">Choose ${e(label.toLowerCase())}</option>${items.map(x=>`<option ${x===value?'selected':''}>${e(x)}</option>`).join('')}</select></label>`;}
function registration(value=state.vehicle.registration){return `<label class="field">Vehicle registration number<div class="reg-wrap"><span class="plate-prefix" aria-hidden="true">IND</span><input class="registration" name="registration" aria-describedby="reg-help" autocomplete="off" placeholder="DL 01 AB 1234" value="${e(value)}" maxlength="13" required></div></label><p id="reg-help" class="field-hint">Use a sample number such as DL 01 AB 1234.</p>`;}
function errors(){return `<div id="form-error" class="error" role="alert">${e(state.error)}</div>`;}
function footer(primary,secondary='',note=''){return `<div class="actions">${primary}${secondary}${note?`<p class="inline-note">${e(note)}</p>`:''}</div>`;}
function focusView(title,content,foot='',opts={}){return `<div class="view ${opts.cls||''}"><header class="focus-header">${action('','back','','icon-btn',`aria-label="Back"`).replace('></button>',`>${icon('arrow-left-filled')}</button>`)}<img class="mini-brand" src="./assets/home-imgLight.svg" alt="Cars24">${state.onboarding?action('Skip','complete-onboarding','','text-btn'):action('','home','','icon-btn close',`aria-label="Back to homepage"`).replace('></button>',`>${icon('cross-large-outline')}</button>`)}</header><div class="form-content" id="page-scroll">${opts.progress?`<p class="progress-label">Step ${opts.progress} of 4</p><div class="progress-track" aria-label="Step ${opts.progress} of 4">${[1,2,3,4].map(i=>`<span class="${i<=opts.progress?'done':''}"></span>`).join('')}</div>`:''}${opts.art!==undefined?`<div class="hero-art small">${glass(opts.art)}</div>`:''}${title?`<h2 tabindex="-1">${title}</h2>`:''}${content}${foot}</div></div>`;}
const SESSION_KEY='cars24-prototype-session-v2';
function saveSession(){
 try{const {previous,...retailState}=state.retail;const scrollTop=app.querySelector('#page-scroll,#l1-scroll')?.scrollTop||0;localStorage.setItem(SESSION_KEY,JSON.stringify({version:2,route:state.route,context:{family:state.context.family,page:state.context.page,scrollTop},history:state.history.map(({route,homeTab,context})=>({route,homeTab,context:{family:context?.family,page:context?.page,scrollTop:context?.scrollTop}})),scenario:state.scenario,consent:state.consent,authReturn:state.authReturn,editing:state.editing,profile:state.profile,draft:state.draft,vehicle:state.vehicle,homeTab:state.homeTab,onboarding:state.onboarding,onboardingComplete:state.onboardingComplete,buyerAuthenticated:state.buyerAuthenticated,locationGranted:state.locationGranted,locationStepComplete:state.locationStepComplete,locationChoice:state.locationChoice,onboardingTask:state.onboardingTask,service:state.service,serviceFamily:state.serviceFamily,loanApproval:state.loanApproval,l1Drafts:state.l1Drafts,saved:[...state.saved],retail:retailState,onboardingState:onboarding.snapshot()}));}catch{}
}
function restoreSession(){
 try{const saved=JSON.parse(localStorage.getItem(SESSION_KEY));if(saved?.version!==2||!saved.profile||!saved.draft)return false;
 const {onboardingState,version,...fields}=saved;Object.assign(state,fields,{saved:new Set(saved.saved||[]),retail:{...freshRetail(),...saved.retail},history:saved.history||[],personaSource:'saved',persona:saved.onboardingComplete?'returning':'first-time'});onboarding.restore(onboardingState);
 if(saved.onboardingComplete){state.onboarding=false;state.route=state.homeTab==='ownership'?'garage':'home';state.context={scrollTop:saved.route==='home'?saved.context?.scrollTop||0:0};}
 else if(['buyer-code'].includes(state.route))state.route='buyer-login';
 else if(['loading','auth-code'].includes(state.route))state.route=state.profile.intent==='sell'?'sell-entry':'intent';
 if(state.route==='home'&&!state.locationStepComplete){onboarding.enter({destination:'home',profile:state.profile});return true;}
 render();return true;}catch{return false;}
}
function go(route,context={},replace=false){if(['home','garage'].includes(route)&&!state.locationStepComplete&&!context.reviewEntry)return onboarding.enter({destination:route,profile:state.profile});if(['home','garage'].includes(route)){state.onboardingComplete=true;state.onboarding=false;}const leavingScroll=app.querySelector('#page-scroll,#l1-scroll');if(leavingScroll)state.context.scrollTop=leavingScroll.scrollTop;clearTimeout(busyTimer);if(!replace)state.history.push({route:state.route,homeTab:state.homeTab,context:{...state.context}});state.route=route;if(route==='home'&&context.tab)state.homeTab=context.tab;if(route==='l1'&&context.page)state.homeTab=context.page;state.context=context;state.error='';render();}
function openL1Page(page,replace=false){
 if(!isL1Page(page))return;
 state.onboarding=false;
 const url=new URL(location.href);url.searchParams.set('view',page==='all'?'l1-all':page);history.replaceState(null,'',url);
 go('l1',{page},replace);
}
function l1Task(label){
 const page=state.context.page||state.homeTab;
 if(page==='buy'){
  if(label==='Get started')return onboarding.start(!!currentHomeContext('buy'));
  const bands=/^Budget cars/.test(label)?[0,7]:/^Mid range cars/.test(label)?[7,15]:/^Premium cars/.test(label)?[15,50]:null;
  const body=['SUV','Hatchback','Sedan'].includes(label)?label:null;
  if(bands||body||label==='Automatic cars')return go('listings',{legacyComposition:true,searchProfile:{...initialProfile(),city:state.profile.city,intent:'buy',...(bands?{budget:`search:${bands[0]}:${bands[1]}`}:{body:body||'Any',transmission:label==='Automatic cars'?'Automatic':'Any'})}});
 }
 const input=app.querySelector('.l1-registration');
 if(/get instant car price/i.test(label)){
  state.vehicle.registration=normalizeRegistration(input?.value||'');
  if(!validRegistration(state.vehicle.registration)){input?.setAttribute('aria-invalid','true');input?.focus();return toast('Enter a vehicle number, for example DL 01 AB 1234.');}
  return lookup('sell');
 }
 if(/get challan details/i.test(label)){
  state.vehicle.registration=normalizeRegistration(input?.value||'');
  if(!validRegistration(state.vehicle.registration)){input?.setAttribute('aria-invalid','true');input?.focus();return toast('Enter a vehicle number, for example DL 01 AB 1234.');}
  return lookup('challan');
 }
 if(/view plans/i.test(label))return openService('Car insurance',{serviceRegistration:normalizeRegistration(input?.value||'')});
 if(/brand|suzuki|hyundai|mahindra|honda|tata|toyota|ford/i.test(label)&&page==='sell')return go('sell-manual');
 if(label==='Apply now')return openService('Loan against car');
 if(label==='Apply for loan')return openService('Personal loan');
 if(label==='View all'&&page==='challan')return toast('The source FAQ content is shown below.');
 if(/car.*loan|used.*loan/i.test(label))return openService('Used-car loan');
 if(/loan against/i.test(label))return openService('Loan against car');
 if(/personal loan/i.test(label))return openService('Personal loan');
 if(/gold/i.test(label))return openService('Gold loan');
 if(/credit/i.test(label))return openService('Check credit score');
 if(/emi/i.test(label))return openService('Pay your EMI');
 if(/bike.*insurance/i.test(label))return openService('Bike insurance');
 if(/health/i.test(label))return openService('Health insurance');
 if(/life.*insurance/i.test(label))return openService('Life insurance');
 if(/insurance|renew|cover/i.test(label))return openService('Car insurance');
 if(/history/i.test(label))return openService('Vehicle history');
 if(/odometer/i.test(label))return openService('Odometer records');
 if(/rto/i.test(label))return openService('RTO records');
 if(/new car check|pdi/i.test(label))return openService('New-car PDI');
 if(/inspection|used car check/i.test(label))return openService('Used-car inspection');
 if(/challan/i.test(label))return go('challan-entry');
 if(/sell|valuation|price for your car/i.test(label))return go('sell-entry');
 if(/scrap/i.test(label))return openService('Scrap my car');
 if(/new bike/i.test(label))return openService('New bikes');
 if(/new car/i.test(label))return openService('New cars');
 if(/car|lakh|suv|hatchback|sedan|browse|explore|view all/i.test(label))return go('listings');
 go('handoff',{title:label,copy:'This is a local service preview. No request, application or payment is submitted.',icon:state.context.page==='loans'?4:5});
}
function updateL1Links(){
 const active=state.route==='l1'?state.context.page:state.route==='home'?state.homeTab:null;
 document.querySelectorAll('[data-action="l1-page"]').forEach(link=>{if(link.dataset.value===active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
}
function openFlowEntry(flow){
 if(!['onboarding','home','clp','cdp'].includes(flow))return;
 const url=new URL(location.href);url.searchParams.set('view',flow);history.replaceState(null,'',url);
 state.onboarding=flow==='onboarding';
 if(flow==='onboarding'){state.editing=false;state.onboardingTask='';return go('intent');}
 if(flow==='home')return go('home',{reviewEntry:true});
 state.homeTab='buy';
 if(flow==='clp')return go('listings',{legacyComposition:true});
 const id=state.context.id&&ALL_DEMO_CARS.some(car=>car.id===state.context.id)?state.context.id:CDP_DEMO_CAR.id;
 retail.visit(id);go('car-detail',{id,legacyComposition:true});
}
function back(){clearTimeout(busyTimer);const prev=state.history.pop();if(prev){const fromSearch=['search','ai-search'].includes(state.route);state.route=prev.route;state.homeTab=prev.homeTab||state.homeTab;state.context=prev.context;state.error='';render();if(fromSearch)app.querySelector('.home-search,.header-search,.clp-search')?.focus({preventScroll:true});}else if(state.onboarding){if(state.route!=='intent')go('intent',{},true);}else go('home',{},true);}
function toast(text){$('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.role='status';n.textContent=text;app.append(n);clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.remove(),2800);}
