function startIntent(intent){if(['checks','challan','insurance','care'].includes(intent))return openOwnershipFamily(intent);if(state.onboarding){state.profile.intent=intent;state.onboardingTask='';if(intent==='buy')return startBuy();if(intent==='sell')return go('sell-entry');if(intent==='challan')return go('challan-entry');return go('onboarding-task',{family:intent});}if(intent==='buy')return startBuy();state.homeTab=intent;state.profile.intent=intent;if(intent==='sell')go('sell-entry');else if(intent==='challan')go('challan-entry');else if(intent==='ownership')go('category',{family:'ownership'});else go('directory');}
function ownershipGroups(){return `<div class="options ownership-groups">${OWNERSHIP_GROUPS.map(([id,label,sub,g])=>choice(label,'ownership-family',id,sub,g)).join('')}</div>`;}
function openOwnershipFamily(family){if(family==='garage'){state.profile.intent='ownership';state.onboardingTask='Manage my car in Garage';state.homeTab='ownership';return completeOnboarding();}state.serviceFamily=family;state.onboardingTask='';state.homeTab='ownership';if(state.onboarding)state.profile.intent='ownership';if(family==='challan'){state.onboardingTask='Check challans';return go('challan-entry');}go(state.onboarding?'ownership-setup':'category',{family});}
function header(selected,tabAction='nav'){if(selected==='ownership')selected='all';return `<header class="app-header"><div class="brand-row"><button class="brand-location" data-action="city"><img src="./assets/home-imgLight.svg" alt="Cars24"><span>${e(state.profile.city||'Choose city')}${icon('chevron-down-small-outline')}</span></button><button class="icon-btn account" aria-label="Your preferences and account" data-action="account">${icon('ownership-line')}</button></div><button class="header-search" data-action="search">${icon('magnifying-glass-outline')}<span>Search cars or services</span></button>${renderServiceTabs({selected,action:tabAction})}</header>`;}
