document.addEventListener('input',ev=>{const n=ev.target;if(sourceFlow.input(n))return;if(n.name==='cdp-downpayment'||n.name==='cdp-tenure'){state.context.financeTouched=true;state.context[n.name==='cdp-downpayment'?'downPayment':'tenure']=Number(n.value);updateCDPFinance();}retail.input(n);onboarding.input(n);booking.input(n);if(n.id==='make-search')renderCoreMarkup($('#make-options'),makeOptions(n.value));if(n.id==='directory-search')renderCoreMarkup($('#directory-results'),serviceRows(SERVICES.filter(s=>(s.label+' '+s.sub).toLowerCase().includes(n.value.toLowerCase()))));if(n.id==='city-search')renderCoreMarkup($('#city-options'),cityOptions(n.value));if(n.matches('.l1-registration')){state.l1Drafts??={};state.l1Drafts[state.context.page||state.homeTab]=normalizeRegistration(n.value);n.value=state.l1Drafts[state.context.page||state.homeTab];return;}if(n.name==='registration'){const value=normalizeRegistration(n.value);if(Object.hasOwn(state.context,'serviceRegistration'))state.context.serviceRegistration=value;else state.vehicle.registration=value;n.value=value;}if(n.name?.startsWith('vehicle-'))state.vehicle[n.name.slice(8)]=n.value;});
document.addEventListener('change',ev=>{const n=ev.target;if(sourceFlow.change(n))return;if(booking.change(n)||retail.change(n))return;if(n.id==='scenario')state.scenario=n.value;if(n.id==='credit-consent'||n.id==='loan-consent')state.consent=n.checked;if(n.name?.startsWith('vehicle-')){state.vehicle[n.name.slice(8)]=n.value;if(n.name==='vehicle-make')state.vehicle.model='';}if(n.name==='service-city')state.profile.city=n.value;if(n.name?.startsWith('filter-')){const key=n.name.slice(7);state.draft[key]=key==='budget'?BUDGETS.find(b=>b[1]===n.value)?.[0]||'any':n.value;if(key==='make')renderCoreMarkup(n.closest('label').querySelector('.make-field-label'),`Make${makeLogoMarkup(n.value)}`);}});
document.addEventListener('submit',ev=>{ev.preventDefault();if(ev.target.matches('[data-flow-search-form]'))sourceFlow.submit();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!ev.defaultPrevented&&!app.querySelector('dialog[open],[role="dialog"]')&&!sourceFlow.snapshot().assistant&&state.route!=='home'){ev.preventDefault();back();}});
function syncDeviceScale(){const screen=document.querySelector('.screen'),bounds=screen.getBoundingClientRect(),scale=bounds.width/360;const flowScale=bounds.width/(screen.classList.contains('is-flow-home')?375:360);screen.style.setProperty('--flow-status-height',(44*flowScale)+'px');screen.style.setProperty('--flow-handle-height',(34*flowScale)+'px');const statusHeight=document.querySelector('.status-bar').getBoundingClientRect().height,safeHeight=document.querySelector('.home-indicator').getBoundingClientRect().height;screen.style.setProperty('--home-native-top-inset',(statusHeight/(scale*.96))+'px');screen.style.setProperty('--home-native-top-space',(statusHeight/scale)+'px');screen.style.setProperty('--home-native-bottom-inset',(safeHeight/scale)+'px');const available=screen.matches('.is-flow-home,.is-flow-listing')?bounds.height:bounds.height-statusHeight-safeHeight;app.style.zoom=String(scale);app.style.width='var(--prototype-logical-width)';app.style.height=(available/scale)+'px';app.style.flex='none';const home=$('#home-view');if(home)home.style.setProperty('--app-height',home.clientHeight+'px');}resizeObserver=new ResizeObserver(syncDeviceScale);resizeObserver.observe(document.querySelector('.screen'));syncDeviceScale();
