const l1Entry=new URLSearchParams(location.search).get('view');
if(l1Entry==='l1-all'||isL1Page(l1Entry)){restoreSession();openL1Page(l1Entry==='l1-all'?'all':l1Entry,true);}else if(new URLSearchParams(location.search).get('view')==='onboarding'){openFlowEntry('onboarding');}else if(new URLSearchParams(location.search).get('view')==='clp'){state.onboarding=false;go('listings',{legacyComposition:true},true);}else if(new URLSearchParams(location.search).get('view')==='cdp'){state.onboarding=false;const id=new URLSearchParams(location.search).get('car');go('car-detail',{id:ALL_DEMO_CARS.some(c=>c.id===id)?id:CDP_DEMO_CAR.id,legacyComposition:true},true);}else if(new URLSearchParams(location.search).get('view')==='cargpt'){state.onboarding=false;openCarGPT();}else if(new URLSearchParams(location.search).get('view')==='booking'){booking.start(new URLSearchParams(location.search).get('kind')==='inspection'?'inspection':'test-drive');}else if(new URLSearchParams(location.search).get('view')==='home'){state.onboarding=false;go('home',{reviewEntry:true},true);}else if(new URLSearchParams(location.search).get('view')==='search'){state.onboarding=false;go('search',{},true);}else if(new URLSearchParams(location.search).get('view')==='roadmap'){state.onboarding=false;go('roadmap',{},true);}else if(!restoreSession())startExperience();

